import{_ as t,o as d,c as a,Q as r}from"./chunks/framework.48927342.js";const p=JSON.parse('{"title":"生日派对邀请邮件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/emails/01-birthday-invitation.md","filePath":"zh/more/maltese/practice/emails/01-birthday-invitation.md"}'),e={name:"zh/more/maltese/practice/emails/01-birthday-invitation.md"},o=r('<h1 id="生日派对邀请邮件" tabindex="-1">生日派对邀请邮件 <a class="header-anchor" href="#生日派对邀请邮件" aria-label="Permalink to &quot;生日派对邀请邮件&quot;">​</a></h1><p><strong>场景：</strong> Anna 邀请朋友 Mark 参加自己的生日派对。</p><h2 id="邮件头部" tabindex="-1">邮件头部 <a class="header-anchor" href="#邮件头部" aria-label="Permalink to &quot;邮件头部&quot;">​</a></h2><p><strong>Lil（收件人 To）：</strong> <a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a><strong>Mingħand（发件人 From）：</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Data（日期）：</strong> 10 ta&#39; Ottubru 2026 <strong>Suġġett（主题）：</strong> Stedina għall-festa ta&#39; għeluq snini</p><h2 id="邮件全文" tabindex="-1">邮件全文 <a class="header-anchor" href="#邮件全文" aria-label="Permalink to &quot;邮件全文&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a><strong>Mingħand:</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Data:</strong> 10 ta&#39; Ottubru 2026 <strong>Suġġett:</strong> Stedina għall-festa ta&#39; għeluq snini</p><p>Għażiż Mark,</p><p>Nispera li inti tajjeb.</p><p>Nixtieq nistedinkom għall-festa ta&#39; għeluq snini nhar is-Sibt.</p><p>Il-festa se tibda fis-sebgħa ta&#39; filgħaxija.</p><p>Se niltaqgħu d-dar tiegħi f&#39;Valletta.</p><p>Ikun hemm ikel, mużika u kejk.</p><p>Tista&#39; ġġib lil xi ħadd miegħek jekk trid.</p><p>Jekk jogħġbok, għidli jekk ġej.</p><p>Nistenna bil-ħerqa li niċċelebraw flimkien.</p><p>Tislijiet, Anna</p></blockquote><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a></p><p><strong>整句：</strong> 收件人（To）：mark.b@gmail.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Lil</td><td>收件人；给……</td><td>邮件头部&quot;To&quot;的马耳他语标签</td></tr><tr><td><a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a></td><td>邮箱地址</td><td>收件人（Mark）的邮箱</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></p><p><strong>整句：</strong> 发件人（From）：anna.c@gmail.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Mingħand</td><td>发件人；来自……</td><td>邮件头部&quot;From&quot;的马耳他语标签，本义&quot;从……那里&quot;</td></tr><tr><td><a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></td><td>邮箱地址</td><td>发件人（Anna）的邮箱</td></tr></tbody></table><p><strong>Malti:</strong> Data: 10 ta&#39; Ottubru 2026</p><p><strong>整句：</strong> 日期：2026 年 10 月 10 日</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Data</td><td>日期</td><td>邮件头部&quot;Date&quot;；马耳他语日期格式为&quot;日 ta&#39; 月 年&quot;</td></tr><tr><td>10</td><td>十</td><td>日期中的日</td></tr><tr><td>ta&#39;</td><td>……的</td><td>连接日和月份</td></tr><tr><td>Ottubru</td><td>十月</td><td>月份名</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Stedina għall-festa ta&#39; għeluq snini</p><p><strong>整句：</strong> 主题：生日派对邀请</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Suġġett</td><td>主题</td><td>邮件头部&quot;Subject&quot;</td></tr><tr><td>Stedina</td><td>邀请</td><td>阴性名词</td></tr><tr><td>għall-festa</td><td>去派对；参加派对</td><td><code>għal</code> + <code>il-festa</code> 的缩合形式</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>għeluq</td><td>庆祝；周年</td><td>与 <code>għeluq snini</code> 连用表示生日</td></tr><tr><td>snini</td><td>我的年岁</td><td><code>snin</code>“年” + <code>-i</code> 第一人称所有格</td></tr></tbody></table><p><strong>Malti:</strong> Għażiż Mark,</p><p><strong>整句：</strong> 亲爱的马克：</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għażiż</td><td>亲爱的</td><td>阳性单数形式，用于称呼男性</td></tr><tr><td>Mark</td><td>马克</td><td>人名</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li inti tajjeb.</p><p><strong>整句：</strong> 希望你一切都好。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nispera</td><td>我希望</td><td>第一人称单数形式</td></tr><tr><td>li</td><td>……这件事；引导从句</td><td>连词</td></tr><tr><td>inti</td><td>你</td><td>第二人称单数代词</td></tr><tr><td>tajjeb</td><td>好的</td><td>阳性形式；女性对象可用 <code>tajba</code></td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Nixtieq nistedinkom għall-festa ta&#39; għeluq snini nhar is-Sibt.</p><p><strong>整句：</strong> 我想邀请你们星期六来参加我的生日派对。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nixtieq</td><td>我想要；我希望</td><td>礼貌表达愿望</td></tr><tr><td>nistedinkom</td><td>我邀请你们</td><td><code>nistieden</code>“我邀请” + <code>-kom</code>“你们”</td></tr><tr><td>għall-festa</td><td>去派对；参加派对</td><td><code>għal</code> + <code>il-festa</code> 的缩合形式</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属/类别连接词</td></tr><tr><td>għeluq</td><td>庆祝；周年</td><td>与 <code>għeluq snini</code> 连用表示生日</td></tr><tr><td>snini</td><td>我的年岁；我的岁数</td><td><code>snin</code>“年” + <code>-i</code> 第一人称所有格</td></tr><tr><td>nhar</td><td>在……那天</td><td>引出星期或日期</td></tr><tr><td>is-Sibt</td><td>星期六</td><td>星期名称通常带定冠词</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Il-festa se tibda fis-sebgħa ta&#39; filgħaxija.</p><p><strong>整句：</strong> 派对将在晚上七点开始。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Il-festa</td><td>派对</td><td>定冠词 + <code>festa</code></td></tr><tr><td>se</td><td>将；会</td><td>将来标记</td></tr><tr><td>tibda</td><td>开始</td><td>第三人称阴性单数，与 <code>festa</code> 呼应</td></tr><tr><td>fis-sebgħa</td><td>在七点</td><td><code>f&#39;</code> + 定冠词钟点形式缩合</td></tr><tr><td>ta&#39;</td><td>……的；在……时段</td><td>连接钟点和时段</td></tr><tr><td>filgħaxija</td><td>在晚上</td><td>时间表达</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Se niltaqgħu d-dar tiegħi f&#39;Valletta.</p><p><strong>整句：</strong> 我们将在我瓦莱塔的家里见面。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Se</td><td>将；会</td><td>将来标记</td></tr><tr><td>niltaqgħu</td><td>我们见面</td><td>第一人称复数形式</td></tr><tr><td>d-dar</td><td>在家；家里</td><td><code>id-dar</code> 的常见缩合形式</td></tr><tr><td>tiegħi</td><td>我的</td><td>所有格代词</td></tr><tr><td>f&#39;Valletta</td><td>在瓦莱塔</td><td><code>f&#39;</code> + 地名；通常不加冠词</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Ikun hemm ikel, mużika u kejk.</p><p><strong>整句：</strong> 会有食物、音乐和蛋糕。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Ikun</td><td>会有；会是</td><td>第三人称形式，常用于表示将来存在</td></tr><tr><td>hemm</td><td>有；那里</td><td>与 <code>ikun</code> 连用表示“会有”</td></tr><tr><td>ikel</td><td>食物</td><td>阳性集合名词</td></tr><tr><td>mużika</td><td>音乐</td><td>阴性名词</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>kejk</td><td>蛋糕</td><td>阳性名词，借词</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Tista&#39; ġġib lil xi ħadd miegħek jekk trid.</p><p><strong>整句：</strong> 如果你愿意，可以带一个人一起来。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tista&#39;</td><td>你可以</td><td>第二人称单数形式</td></tr><tr><td>ġġib</td><td>带来</td><td><code>ġib</code>“带来”的变位形式</td></tr><tr><td>lil</td><td>对；给；引出人的宾语</td><td>人称宾语标记/介词</td></tr><tr><td>xi</td><td>某个；一些</td><td>不定限定词</td></tr><tr><td>ħadd</td><td>人</td><td>与 <code>xi</code> 连用表示“某个人”</td></tr><tr><td>miegħek</td><td>和你一起</td><td><code>miegħ</code>“和” + <code>-ek</code>“你”</td></tr><tr><td>jekk</td><td>如果</td><td>连词</td></tr><tr><td>trid</td><td>你想；你愿意</td><td>第二人称单数形式</td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> Jekk jogħġbok, għidli jekk ġej.</p><p><strong>整句：</strong> 麻烦告诉我你是否会来。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Jekk jogħġbok</td><td>请；麻烦你</td><td>固定礼貌表达</td></tr><tr><td>għidli</td><td>告诉我</td><td><code>għid</code>“说/告诉” + <code>-li</code>“我”</td></tr><tr><td>jekk</td><td>是否；如果</td><td>此处引出间接疑问</td></tr><tr><td>ġej</td><td>来；将来</td><td>阳性形式；女性对象可用 <code>ġejja</code></td></tr></tbody></table><h3 id="_8" tabindex="-1">8. <a class="header-anchor" href="#_8" aria-label="Permalink to &quot;8.&quot;">​</a></h3><p><strong>Malti:</strong> Nistenna bil-ħerqa li niċċelebraw flimkien.</p><p><strong>整句：</strong> 我期待和你们一起庆祝。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nistenna</td><td>我等待；我期待</td><td>第一人称单数形式</td></tr><tr><td>bil-ħerqa</td><td>期待地；热切地</td><td>固定副词短语</td></tr><tr><td>li</td><td>……；引出从句</td><td>连词</td></tr><tr><td>niċċelebraw</td><td>我们庆祝</td><td>第一人称复数形式</td></tr><tr><td>flimkien</td><td>一起</td><td>副词</td></tr></tbody></table><p><strong>Malti:</strong> Tislijiet, Anna</p><p><strong>整句：</strong> 此致敬意，安娜（邮件落款）。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tislijiet</td><td>此致敬意；致以问候</td><td>正式邮件/信件落款用语，本义&quot;问候/致意&quot;</td></tr><tr><td>Anna</td><td>安娜</td><td>人名</td></tr></tbody></table>',57),i=[o];function n(l,h,s,g,b,c){return d(),a("div",null,i)}const k=t(e,[["render",n]]);export{p as __pageData,k as default};
